\"\"\"Send private text prompts to OpenAI's Responses API using only the standard library.

A prompt is \"private\" by setting "'``store=False`` so the request and response are not
stored by OpenAI and are not used for model distillation or training. See
https://platform.openai.com/docs/api-reference/responses for the full schema.
"""

import json
import os
import sys
import urllib.error
import urllib.request

DEFAULT_BASE_URL = "https://api.openai.com/v1"
DEFAULT_MODEL = "gpt-4o-mini"
DEFAULT_TIMEOUT = 60


class OpenAIClientError(Exception):
    """Raised when a Responses API request fails."""


def _extract_text(response):
    """Return the assistant text from a Responses API response body."""
    if isinstance(response.get("output_text"), str):
        return response["output_text"]
    for item in response.get("output", []) or []:
        for part in item.get("content", []) or []:
            if part.get("type") == "output_text" and "text" in part:
                return part["text"]
    return ""


def _error_detail(exc):
    try:
        return exc.read().decode("utf-8")
    except Exception:
        return ""


def send_private_prompt(
    prompt,
    *,
    model=DEFAULT_MODEL,
    instructions=None,
    temperature=None,
    max_output_tokens=None,
    api_key=None,
    base_url=DEFAULT_BASE_URL,
    timeout=DEFAULT_TIMEOUT,
):
    """Send a private text prompt to the Responses API and return the reply text.

    Arguments:
        prompt: plain text to send as the user turn.
        model: model name, e.g. ``"gpt-4o-mini"`` (default) or ``"gpt-4o"``.
        instructions: optional system-level instructions.
        temperature: optional sampling temperature.
        max_output_tokens: optional cap on generated tokens.
        api_key: API key; defaults to ``OPENAI_API_KEY`` env var.
        base_url: API base URL; defaults to ``https://api.openai.com/v1``.
        timeout: request timeout in seconds.

    ``store`` is always set to ``False`` so the exchange is not retained.
    """
    key = api_key or os.environ.get("OPENAI_API_KEY")
    if not key:
        raise OpenAIClientError(
            "No API key: set OPENAI_API_KEY or pass api_key=..."
        )

    payload = {"model": model, "input": prompt, "store": False}
    if instructions is not None:
        payload["instructions"] = instructions
    if temperature is not None:
        payload["temperature"] = temperature
    if max_output_tokens is not None:
        payload["max_output_tokens"] = max_output_tokens

    request = urllib.request.Request(
        f"{base_url.rstrip('"'/')}/responses\",
        data=json.dumps(payload).encode(\"utf-8\"),
        headers={
            \"Authorization\": f\"Bearer {key}\",
            \"Content-Type\": \"application/json\",
        },
        method=\"POST\",
    )

    try:
        with urllib.request.urlopen(request, timeout=timeout) as resp:
            body = resp.read()
    except urllib.error.HTTPError as exc:
        raise OpenAIClientError(
            f\"OpenAI API error {exc.code}: {_error_detail(exc)}\"
        ) from exc
    except urllib.error.URLError as exc:
        raise OpenAIClientError(f\"Request failed: {exc.reason}\") from exc

    return _extract_text(json.loads(body.decode(\"utf-8\")))


def _main():
    if len(sys.argv) > 1:
        text = \" \".join(sys.argv[1:])
    else:
        text = sys.stdin.read().strip()
    if not text:
        sys.exit(\"Usage: python openai_client.py PROMPT  (or pipe a prompt via stdin)\")
    try:
        print(send_private_prompt(text))
    except OpenAIClientError as exc:
        sys.exit(str(exc))


if __name__ == \"__main__\":
    _main()
PYEOF
